   Object formatAndRequest(FieldItem item) {
      switch (item.getFormat()){
         case BYTE: 
            byte byteItem = item.getValueAsByte();
            return byteItem;
         case BYTEARRAY:
            byte [] byteArrayItem = item.getValueAsByteArray();      
            return byteArrayItem;
         case CIDDATA: 
            CidData cidDataItem = item.getValueAsCidData();
            return cidDataItem;
         case CIDFIELDDATA: 
            double cidFieldDataItem = item.getValueAsCidFieldData().getValue();  // price/value
            
            // The CIDFIELDDATA format provides the price/value (e.g. 100.00) of the item, as well as the following details:
            //
            // 1. Price (e.g. 100.00) item.getValueAsCidFieldData().getValue()
            // 2. Size (e.g. 1000) item.getValueAsCidFieldData().getSize()
            // 3. Exchange (e.g. NYMEX) item.getValueAsCidFieldData().getExchange() 
            // 4. Exchange Time (e.g. 2012-01-01T12:00:00) item.getValueAsCidFieldData().getExchangeTimeAsInstant()
            
            
            
            // We will test to see what type of data this item is and assign the size to the
            // appropriate global variable
            switch (item.getId()) {
               case Quote.FieldItem.LRT_TYPE_LAST:  
                  gLastSize =  String.format("%.5f", item.getValueAsCidFieldData().getSize());
                  gLastExg = item.getValueAsCidFieldData().getExchange();
                  break;
               case Quote.FieldItem.LRT_TYPE_BID:                    
                  gBidSize = String.format("%.5f", item.getValueAsCidFieldData().getSize());
                  gBidExg = item.getValueAsCidFieldData().getExchange();
                  break;
               case Quote.FieldItem.LRT_TYPE_ASK: 
                  gAskSize =  String.format("%.5f", item.getValueAsCidFieldData().getSize());
                  gAskExg = item.getValueAsCidFieldData().getExchange();
                  break;
            }
            
            return cidFieldDataItem;
         case CIDPRICEFIELDDATA:            
            double cidPriceFieldDataItem = item.getValueAsCidPriceFieldData().getValue();                        
            return cidPriceFieldDataItem;
         case DATE: 
            // Times come as UTC values.  
            // We will convert them to human-readable form and convert to the timezone of the local machine.
            
            String format = "EEE MMM dd yyyy hh:mm:ss a";          // Format looks like: 11:09:41 PM
            SimpleDateFormat sdf = new SimpleDateFormat(format);   // Sets the formatter
            TimeZone tz = TimeZone.getDefault();                   // Gets the timezone of the local machine
            sdf.setTimeZone(tz);                                   // Sets the format to the local timezone
                        
            long dateItem = item.getValueAsInteger(false) * 1000L; // Gets the UTC value from the response
            Date date = new Date(dateItem);                        // Converts the UTC value into a Date object
            
            return sdf.format(date).toString();                    // Formats the date into the local timezone
         case DOUBLE: 
            double doubleItem = item.getValueAsDouble();            
            return doubleItem;
         case INT32: 
            int int32Item = item.getValueAsInteger(false);            
            return int32Item;
         case SHORT: 
            short shortItem = item.getValueAsShort(true);            
            return shortItem;
         case STRING: 
            String stringItem = item.getValueAsString();            
            return stringItem;
         case STRINGARRAY: 
            byte [] stringArrayItem = item.getValueAsByteArray();            
            return stringArrayItem;
         case UINT32:
            int uint32Item = item.getValueAsInteger(false);            
            return uint32Item;
         case UINT64: 
            BigInteger uint64Item = item.getValueAsBigInteger(false);
            return uint64Item;
         default:
            break;
      }

      // An asterisk will proceed the value to indicate it was not handled by the switch statement; this should not happen
      return "*" + item.getValue().toString();

   }// end formatAndRequest
   
   // Required to implement this class, but not handled by this sample
   public void onAdded(SymbolEvent event) {
   }

